    "shastricContext": "रुद्र सूक्त का संजीवनी महामंत्र। महर्षि मार्कण्डेय और शुक्राचार्य द्वारा सिद्ध अकाल मृत्यु निवारक, रोग नाशक एवं मोक्षदायक महामंत्र।",
