    "transliteration": "oṃ yaj jāgrato dūram udaiti daivaṃ tad u suptasya tathaivaiti |\ndūraṅgamaṃ jyotiṣāṃ jyotir ekaṃ tan me manaḥ śivasaṅkalpam astu || 1 ||",
