    "sanskrit": "ॐ यत्ते॒ मध्यं॑ पृथि॒वि यच्च॒ नभ्यं॒ यास्त॑ ऊ॒र्जस्त॒न्वः॒ संब॑भू॒वुः।\nतासु॑ नो धे॒ह्य॒भि नः॑ पवस्व मा॒ता भूमिः॑ पु॒त्रो अ॒हं पृ॑थि॒व्याः।\nप॒र्जन्यः॑ पि॒ता स उ॑ नः पिपर्तु॥१२॥",
