    "shastricContext": "विश्व साहित्य का महानतम ब्रह्माण्डीय उद्भव सूक्त (Cosmological Hymn of Creation)। मैक्स मूलर और स्वामी विवेकानंद ने इसे मानवीय प्रज्ञा की सर्वोच्च दार्शनिक ऊंचाई माना है।",
    "audioUrl": null,
