    "sanskrit": "सु॒षा॒र॒थिरश्वा॑निव॒ यन्म॑नु॒ष्यान्नेनी॑यते॒ऽभीशु॑भिर्वा॒जिन॑ इव।\nहृत्प्र॑ति॒ष्ठं यद॒जिरं॒ जवि॑ष्ठं॒ तन्मे॒ मनः॑ शि॒वस॑ङ्क॒ल्पम॑स्तु॥६॥",
