    "viniyoga": "ॐ अस्य शान्तिमन्त्रस्य दध्यङ्ङाथर्वण ऋषिः, निचृत् स्वराट् छन्दः, विश्वे देवा देवता, विश्वशान्त्यर्थे कर्मसमाप्तौ च विनियोगः।",
