    "transliteration": "oṃ kasminn aṅge tapo asyādhi tiṣṭhati kasminn aṅga ṛtam asyādhyāhitam |\nkva vrataṃ kva śraddhāsya tiṣṭhati kasminn aṅge satyam asya pratiṣṭhitam || 1 ||",
