    "transliteration": "oṃ iyaṃ samit pṛthivī dyaur dvitīyotāntarikṣaṃ samidhā pṛṇāti |\nbrahmacārī samidhā mekhalayā śrameṇa lokāṃs tapasā piparti || 1 ||",
